mapper.select:
SELECT ar.id, ar.audit_no AS auditNo, ar.audit_type AS auditType, ar.business_id AS stationId, pcs.name AS stationName, pcs.location_name AS stationLocation, ar.applicant_id AS applicantId, u.name AS applicantName, u.phone AS applicantPhone, ar.title, ar.current_status AS currentStatus, ar.priority, adm.name AS currentAdminName, ar.submit_time AS submitTime FROM audit_record ar LEFT JOIN user_info u ON ar.applicant_id = u.id LEFT JOIN private_charge_station pcs ON ar.business_id = pcs.id LEFT JOIN admin_info adm ON ar.current_admin_id = adm.id WHERE ar.is_deleted = 0 AND ar.audit_type IN (2, 3)
AND ar.audit_type = #{query.auditType}
AND ar.current_status = #{query.status}
AND ar.priority = #{query.priority}
AND ar.business_id = #{query.stationId}
AND (ar.audit_no LIKE CONCAT('%', #{query.keyword}, '%') OR ar.title LIKE CONCAT('%', #{query.keyword}, '%'))
AND ar.submit_time >= #{query.startTime}
AND ar.submit_time <= CONCAT(#{query.endTime}, ' 23:59:59')
ORDER BY ar.priority DESC, ar.submit_time DESC
